function doblar(n: number): number {
  n = n * 2;   // modifica la copia local únicamente
  return n;
}
let x = 10;
doblar(x);
console.log(x);   // 10 — sin cambio ✓

function agregarItem(arr: number[], item: number): void {
  arr.push(item);  // modifica el MISMO objeto en heap
}
